    mock_async_http_client.queue_response(status_code=200, body={"success": True})
    result = await async_client.metrics.unregister_metrics_viewer(hostId=1.0, viewerSessionId="x")
    sent = mock_async_http_client.requests[0]
    assert sent.method == "POST"
    assert sent.url.endswith("/metrics/unregister-viewer")
    assert sent.json == {"hostId": 1.0, "viewerSessionId": "x"}
    assert result.to_dict() == {"success": True}


